1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Dtos;
4	
5	namespace seed_b_backend.Api.Application;
6	
7	public class ProductQueryService(AppDbContext db)
8	{
9	    private const int PageSize = 20;
10	
11	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
12	        int page = 1,
13	        string? categoryId = null,
14	        string? subcategoryId = null,
15	        string? sortBy = null,
16	        string? sortDir = null,
17	        CancellationToken cancellationToken = default)
18	    {
19	        if (page < 1)
20	        {
21	            page = 1;
22	        }
23	
24	        var query = db.Products.AsNoTracking().AsQueryable();
25	
26	        if (!string.IsNullOrWhiteSpace(subcategoryId))
27	        {
28	            query = query.Where(p => p.SubcategoryId == subcategoryId);
29	        }
30	        else if (!string.IsNullOrWhiteSpace(categoryId))
31	        {
32	            query = query.Where(p => p.Subcategory.CategoryId == categoryId);
33	        }
34	
35	        var descending = string.Equals(sortDir?.Trim(), "desc", StringComparison.OrdinalIgnoreCase);
36	        query = sortBy?.Trim().ToLowerInvariant() switch
37	        {
38	            "price" => descending
39	                ? query.OrderByDescending(p => p.Offers.Select(o => (decimal?)o.Price).Min())
40	                : query.OrderBy(p => p.Offers.Select(o => (decimal?)o.Price).Min()),
41	            "name" => descending
42	                ? query.OrderByDescending(p => p.Name)
43	                : query.OrderBy(p => p.Name),
44	            _ => query.OrderBy(p => p.Id)
45	        };
46	
47	        var totalCount = await query.CountAsync(cancellationToken);
48	        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);
49	
50	        if (pageCount > 0 && page > pageCount)
51	        {
52	            page = pageCount;
53	        }
54	
55	        var items = await query
56	            .Skip((page - 1) * PageSize)
57	            .Take(PageSize)
58	            .Select(p => new ProductListItemDto
59	            {
60	                Id = p.Id,
61	                Name = p.Name,
62	                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
63	            })
64	            .ToListAsync(cancellationToken);
65	
66	        return new PagedResultDto<ProductListItemDto>
67	        {
68	            Items = items,
69	            TotalCount = totalCount,
70	            PageCount = pageCount,
71	            Page = page,
72	            PageSize = PageSize
73	        };
74	    }
75	}
76

