using Microsoft.EntityFrameworkCore;
using seed_b_backend.Api.Data;
using seed_b_backend.Api.Dtos;

namespace seed_b_backend.Api.Application;

public class ProductQueryService(AppDbContext db)
{
    private const int PageSize = 20;

    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
        int page = 1,
        string? categoryId = null,
        string? subcategoryId = null,
        string? sortBy = null,
        string? sortDir = null,
        CancellationToken cancellationToken = default)
    {
        if (page < 1)
        {
            page = 1;
        }

        var query = db.Products.AsNoTracking().AsQueryable();

        if (!string.IsNullOrWhiteSpace(subcategoryId))
        {
            query = query.Where(p => p.SubcategoryId == subcategoryId);
        }
        else if (!string.IsNullOrWhiteSpace(categoryId))
        {
            query = query.Where(p => p.Subcategory.CategoryId == categoryId);
        }

        var descending = string.Equals(sortDir?.Trim(), "desc", StringComparison.OrdinalIgnoreCase);
        query = sortBy?.Trim().ToLowerInvariant() switch
        {
            "price" => descending
                ? query.OrderByDescending(p => p.Offers.Select(o => (decimal?)o.Price).Min())
                : query.OrderBy(p => p.Offers.Select(o => (decimal?)o.Price).Min()),
            "name" => descending
                ? query.OrderByDescending(p => p.Name)
                : query.OrderBy(p => p.Name),
            _ => query.OrderBy(p => p.Id)
        };

        var totalCount = await query.CountAsync(cancellationToken);
        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);

        if (pageCount > 0 && page > pageCount)
        {
            page = pageCount;
        }

        var items = await query
            .Skip((page - 1) * PageSize)
            .Take(PageSize)
            .Select(p => new ProductListItemDto
            {
                Id = p.Id,
                Name = p.Name,
                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
            })
            .ToListAsync(cancellationToken);

        return new PagedResultDto<ProductListItemDto>
        {
            Items = items,
            TotalCount = totalCount,
            PageCount = pageCount,
            Page = page,
            PageSize = PageSize
        };
    }
}

import { DecimalPipe } from '@angular/common';
import { Component, inject, OnInit, signal } from '@angular/core';

import { PagedResult, ProductListItem, ProductsApi } from '../../core/api/products.api';
import { CategoryNav, CategorySelection } from './category-nav/category-nav';

@Component({
  selector: 'app-catalog',
  imports: [DecimalPipe, CategoryNav],
  templateUrl: './catalog.html',
  styleUrl: './catalog.scss',
})
export class Catalog implements OnInit {
  private readonly productsApi = inject(ProductsApi);

  protected readonly page = signal(1);
  protected readonly result = signal<PagedResult<ProductListItem> | null>(null);
  protected readonly loading = signal(false);
  protected readonly error = signal(false);
  protected readonly selectedCategoryId = signal<string | undefined>(undefined);
  protected readonly selectedSubcategoryId = signal<string | undefined>(undefined);
  protected readonly sortBy = signal<'price' | 'name' | undefined>(undefined);
  protected readonly sortDir = signal<'asc' | 'desc' | undefined>(undefined);

  ngOnInit(): void {
    this.loadPage(1);
  }

  protected goToPage(page: number): void {
    if (this.loading() || page < 1 || (this.result() && page > this.result()!.pageCount)) {
      return;
    }
    this.loadPage(page);
  }

  protected onCategorySelectionChange(selection: CategorySelection): void {
    if (this.loading()) {
      return;
    }
    this.selectedCategoryId.set(selection.categoryId ?? undefined);
    this.selectedSubcategoryId.set(selection.subcategoryId ?? undefined);
    this.loadPage(1);
  }

  protected onSortSelectionChange(value: string): void {
    if (this.loading()) {
      return;
    }
    switch (value) {
      case 'price-asc':
        this.sortBy.set('price');
        this.sortDir.set('asc');
        break;
      case 'price-desc':
        this.sortBy.set('price');
        this.sortDir.set('desc');
        break;
      case 'name-asc':
        this.sortBy.set('name');
        this.sortDir.set('asc');
        break;
      case 'name-desc':
        this.sortBy.set('name');
        this.sortDir.set('desc');
        break;
      default:
        this.sortBy.set(undefined);
        this.sortDir.set(undefined);
    }
    this.loadPage(1);
  }

  private loadPage(page: number): void {
    this.loading.set(true);
    this.error.set(false);
    this.productsApi
      .getProducts(page, this.selectedCategoryId(), this.selectedSubcategoryId(), this.sortBy(), this.sortDir())
      .subscribe({
        next: (result) => {
          this.page.set(result.page);
          this.result.set(result);
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
          this.error.set(true);
        },
      });
  }
}

