        for (var i = 1; i <= 25; i++)
        {
            var id = $"P{i:D2}";
            _db.Products.Add(new Product
            {
                Id = id,
                Name = $"Produkt {i:D2}",
                Description = "Beschreibung",
                Subcategory = subcategory
