  it('reloads page 1 with the selected sort parameters when a sort option is chosen', () => {
    productsApiMock.getProducts.mockReturnValueOnce(of(pageResult(1, [{ id: 'P1', name: 'Produkt 1', lowestPrice: 10 }])));
